        if(order.tier()==Order.Tier.MEMBER) subtotal=order.units()*180;
        else subtotal=order.units()*200;
        int shipping;
        if(order.units()==0 || order.delivery()==Order.Delivery.PICKUP) shipping=0;
        else if(order.delivery()==Order.Delivery.EXPRESS) shipping=900;
        else if(subtotal>=2000) shipping=0;
        else shipping=500;
        return order.tier()+"|"+order.delivery()+"|"+order.units()+"|"+subtotal+"|"+shipping+"|"+(subtotal+shipping);
    }
}

package checkout;
import java.util.Objects;
public record Order(int units,Tier tier,Delivery delivery) {
    public enum Tier { REGULAR, MEMBER }
    public enum Delivery { PICKUP, STANDARD, EXPRESS }
    public Order {
        if (units<0 || units>100) throw new IllegalArgumentException("units must be 0..100");
        Objects.requireNonNull(tier,"tier");Objects.requireNonNull(delivery,"delivery");
    }
}

package checkout;
public record Totals(int subtotal,int shipping) {
    public Totals {
        if(subtotal<0 || shipping<0)throw new IllegalArgumentException("negative amount");
    }
    public int total(){ return Math.addExact(subtotal,shipping); }
}

